package dev.abros.rivet.client;
import com.google.gson.*;
import dev.abros.rivet.core.Json;
import net.minecraft.client.Minecraft;
import java.util.*;
/** Local home composition, shared by narrow and wide layouts. */
final class HomeLayout {
 static final List<String> KEYS=List.of("announcements","groups","action:players","action:groups","action:help","action:admin","action:settings","action:notifications","action:skins","action:trades");
 private static List<String> order=new ArrayList<>(KEYS);private static Set<String> hidden=new HashSet<>();private static Set<String> favorites=new HashSet<>();private static boolean loaded;
 static void load(){if(loaded)return;loaded=true;try{var path=file();if(java.nio.file.Files.exists(path)){var j=Json.read(path);if(j.has("order")){var chosen=new LinkedHashSet<String>();for(var e:j.getAsJsonArray("order"))if(KEYS.contains(e.getAsString()))chosen.add(e.getAsString());chosen.addAll(KEYS);order=new ArrayList<>(chosen);}if(j.has("favorites"))for(var e:j.getAsJsonArray("favorites"))if(KEYS.contains(e.getAsString()))favorites.add(e.getAsString());if(j.has("hidden"))for(var e:j.getAsJsonArray("hidden"))if(KEYS.contains(e.getAsString()))hidden.add(e.getAsString());}}catch(Exception ignored){}}
 private static java.nio.file.Path file(){return Minecraft.getInstance().gameDirectory.toPath().resolve("rivet/home-layout.json");}
 static List<String> order(){load();var available=MenuActions.available();return order.stream().filter(k->!k.startsWith("action:")||available.containsKey(k.substring(7))).toList();}
 static boolean visible(String key){load();return KEYS.contains(key)&&(key.startsWith("action:")?favorites.contains(key)&&MenuActions.available().containsKey(key.substring(7)):!hidden.contains(key));}
 static String name(String key){if(key.startsWith("action:"))return Client.text("menu.favorite")+" · "+MenuActions.available().getOrDefault(key.substring(7),CommunityScreen.name(key.substring(7)));return switch(key){case "announcements"->Client.text("server.notices");case "groups"->Client.text("ui.groups_903e08f2");default->key;};}
 static void toggle(String key)throws Exception{load();if(!KEYS.contains(key))return;var target=key.startsWith("action:")?favorites:hidden;var previous=new HashSet<>(target);if(!target.remove(key))target.add(key);try{save();}catch(Exception failure){target.clear();target.addAll(previous);throw failure;}}
 static void moveTo(String key,int index)throws Exception{load();var shown=order();int at=shown.indexOf(key);if(at<0||index<0||index>=shown.size()||at==index)return;String target=shown.get(index);var previous=new ArrayList<>(order);order.remove(key);order.add(order.indexOf(target)+(at<index?1:0),key);try{save();}catch(Exception failure){order=previous;throw failure;}}
 static void reset()throws Exception{load();var previousOrder=new ArrayList<>(order);var previousHidden=new HashSet<>(hidden);var previousFavorites=new HashSet<>(favorites);order=new ArrayList<>(KEYS);hidden.clear();favorites.clear();try{save();}catch(Exception failure){order=previousOrder;hidden=previousHidden;favorites=previousFavorites;throw failure;}}
 private static void save()throws Exception{Json.write(file(),Map.of("order",order,"hidden",hidden,"favorites",favorites));}
 static JsonArray actions(){load();var rows=new JsonArray();MenuActions.available().forEach((key,label)->{if(visible("action:"+key)){var row=new JsonObject();row.addProperty("id","local:action:"+key);row.addProperty("section","home");row.addProperty("title",label);row.addProperty("preview",Client.text("menu.favorite.open"));rows.add(row);}});return rows;}
 static JsonArray arrange(JsonArray input){load();var list=new ArrayList<JsonObject>();for(var e:input){var row=e.getAsJsonObject();String section=Json.opt(row,"section","");if(section.equals("task")||dev.abros.rivet.core.RetiredFeatures.contains(section))continue;String key=key(row);if(key.isEmpty()||visible(key))list.add(row);}list.sort(Comparator.comparingInt(HomeLayout::urgency).thenComparingInt(r->{int n=order.indexOf(key(r));return n<0?-1:n;}));var out=new JsonArray();list.forEach(out::add);return out;}
 private static String key(JsonObject row){String id=Json.opt(row,"id","");if(id.startsWith("local:action:"))return "action:"+id.substring(13);if(id.equals("local:pinned"))return "announcements";return switch(Json.opt(row,"section","")){case "groups"->"groups";default->"";};}
 private static int urgency(JsonObject row){if(Json.opt(row,"id","").equals("local:moderation-vote"))return 0;if(Json.opt(row,"attention","").equals(Client.text("ui.you_have_been_invited_78128de8")))return 1;return 3;}
}
